using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Localization;using MiniStore.Application.DTOs.Purchases;using MiniStore.Application.Services;using MiniStore.Web.Authorization;using MiniStore.Web.Middleware.Api;
namespace MiniStore.Web.Controllers.Api.V1;[ApiController,Authorize,Route("api/v1/purchase-service-acceptances")]
public sealed class PurchaseServiceAcceptancesApiController(PurchaseServiceAcceptanceService service,IStringLocalizer<SharedResource>localizer):ControllerBase{
[HttpGet,PermissionAuthorize("PurchaseServiceAcceptances.View")]public async Task<ActionResult<List<PurchaseServiceAcceptanceDto>>>GetAll()=>Ok(await service.GetAllAsync());
[HttpGet("{id:int}"),PermissionAuthorize("PurchaseServiceAcceptances.View")]public async Task<ActionResult<PurchaseServiceAcceptanceDto>>Get(int id){var x=await service.GetAsync(id);return x is null?NotFound():Ok(x);}
[HttpGet("create-form"),PermissionAuthorize("PurchaseServiceAcceptances.Create")]public async Task<IActionResult>GetCreateForm(int purchaseOrderId){var x=await service.GetCreatePageAsync(purchaseOrderId);return string.IsNullOrWhiteSpace(x.PurchaseOrderNumber)?NotFound():Ok(x);}
[HttpPost,ValidateAntiForgeryToken,PermissionAuthorize("PurchaseServiceAcceptances.Create")]public async Task<IActionResult>Create(CreatePurchaseServiceAcceptanceDto input){try{return Ok(new{id=await service.CompleteAsync(input)});}catch(Exception e)when(e is ArgumentException or InvalidOperationException){ModelState.AddModelError(string.Empty,localizer[e.Message]);return InternalApiProblemFactory.Validation(HttpContext,ModelState,localizer["One or more validation errors occurred."],InternalApiProblemCodes.Validation);}}}
